
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbe38_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbe38", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.753835439969327e+00, -2.701720783382272e+00, -2.628730478001621e+00, -2.527695655476536e+00, -2.390185375067124e+00, -2.207526363273507e+00, -1.973212681857595e+00, -1.687239441926936e+00, -1.361698084200831e+00, -1.021743597734545e+00, -6.905351241715408e-01, -4.810573993615899e-01, -4.222270404604331e-01, -3.450728808841336e-01, -2.473190967763821e-01, -1.554336540579538e-01, -8.354849035971966e-02, -3.095262527262725e-02, -6.757456437413735e-03, -7.601263430725420e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


